-- Refresh only eleven reviewed fact policies. Preserve source health, RLS, operational workflows and external-approval requirements.
begin;
do $review$
declare item jsonb;b public.hb_service_bindings%rowtype;p public.hb_policy_versions%rowtype;new_rules jsonb;source_url text;review_tag text:='partial-official-fields-2026-10-15';
begin
 for item in select value from jsonb_array_elements($facts$[{"slug":"إصدار-بطاقة-منشأة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e6d","requirements":["رخصة تجارية وتفويض توقيع وعقد تأسيس للشراكة؛ متطلبات الإمارة حسب الحالة.","للجهة الحكومية: مرسوم التأسيس وقرار المجلس وخطاب الطلب والتفويض."],"fees":"البنود المنشورة: 100 درهم للطلب، 100 للسنة، 100 للخدمات الذكية، و2000 لاشتراك النظام. ترد ضمانات مشروطة: 1000 للاشتراك و20 للإيداع و75000 للمنشأة السياحية؛ لا تجمعها دون تحديد الفئة.","duration":"يومان وفق البطاقة الرسمية؛ ليست ضمان قبول.","conditions":"رخصة سارية وهوية أو رقم موحد للمفوض. التقديم عبر مقدم معتمد؛ منشأة المنطقة الحرة تقدم عبر سلطتها.","specialCases":"ICP","scopeUnresolved":false,"officialSteps":["ادخل إلى قناة ICP الرسمية وحدد فئة المنشأة.","راجع البيانات وأرفق المستندات التي لم يسترجعها الربط.","راجع الرسوم المشروطة وسدد ما ينطبق.","تابع قرار الهيئة وإصدار البطاقة أو تحديثها."]},{"slug":"تجديد-بطاقة-المنشأة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e6e","requirements":["الرخصة وشركاء LLC، تفويض التوقيع، وعقد الشراكة والمتطلبات المحلية بحسب الفئة.","للجهة الحكومية: مرسوم التأسيس وقرار المجلس وخطاب الطلب والتفويض."],"fees":"100 درهم لكل سنة تجديد، و1000 لاشتراك النظام و100 خدمات ذكية. يظهر رسم طلب 100 لفئة في البطاقة؛ حدد الفئة ولا تعتبر البنود إجماليًا موحدًا.","duration":"يومان وفق البطاقة الرسمية؛ ليست ضمان قبول.","conditions":"رخصة سارية وسداد الغرامات واستكمال النواقص. أبلغ الهيئة بتغييرات بيانات المنشأة.","specialCases":"ICP","scopeUnresolved":false,"officialSteps":["ادخل إلى قناة ICP الرسمية وحدد فئة المنشأة.","راجع البيانات وأرفق المستندات التي لم يسترجعها الربط.","راجع الرسوم المشروطة وسدد ما ينطبق.","تابع قرار الهيئة وإصدار البطاقة أو تحديثها."]},{"slug":"تعديل-أو-إضافة-بيانات-بطاقة-المنشأة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e70","requirements":["الرخصة وتفويض التوقيع؛ موافقة مبدئية عند إضافة شريك أو تغيير النشاط، ووكالة عند التفويض.","مستند الشركاء أو المرسوم الأحدث وخطاب التعديل بحسب فئة المنشأة."],"fees":"بحسب العملية: 200 درهم لتعديل/إضافة خدمة إلكترونية؛ 100 لإضافة فئة خدمة؛ 5000 لامتياز تأشيرة زيارة؛ 500 لزيادة عددها؛ و100 خدمات ذكية. ليست بنودًا تجمع لكل تعديل.","duration":"يومان وفق البطاقة الرسمية؛ ليست ضمان قبول.","conditions":"بطاقة منشأة قائمة؛ سداد الغرامات وتسوية أوضاع العمال واستكمال النواقص وفق الحالة.","specialCases":"ICP","scopeUnresolved":false,"officialSteps":["ادخل إلى قناة ICP الرسمية وحدد فئة المنشأة.","راجع البيانات وأرفق المستندات التي لم يسترجعها الربط.","راجع الرسوم المشروطة وسدد ما ينطبق.","تابع قرار الهيئة وإصدار البطاقة أو تحديثها."]},{"slug":"إلغاء-بطاقة-المنشأة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e6f","requirements":["الرخصة؛ للقطاع الخاص نسخة الرخصة الملغاة، ومتطلبات الجهة المحلية بحسب الإمارة."],"fees":"50 درهم لإلغاء البطاقة، و50 لطلب إلغاء اشتراك النظام، و100 للخدمات الذكية؛ راجع البنود المنطبقة على فئة المنشأة.","duration":"يومان وفق البطاقة الرسمية؛ ليست ضمان قبول.","conditions":"ألغ الرخصة التجارية أولًا، وسدد الغرامات وسوِّ أوضاع العمال واستكمل النواقص.","specialCases":"ICP","scopeUnresolved":false,"officialSteps":["اختر إلغاء بطاقة المنشأة عبر ICP.","راجع البيانات والمستندات المطلوبة.","سدد الرسوم المنطبقة.","تابع قرار الهيئة ونتيجة الإلغاء."]},{"slug":"إلغاء-تأشيرة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e63","requirements":["جواز السفر وصورة شخصية؛ خطاب المنطقة الحرة عند انطباقه."],"fees":"50 درهم لإلغاء إذن الدخول و100 للخدمات الذكية؛ غرامة التجاوز 50 لليوم بعد المهلة الخاصة بنوع الإذن.","duration":"يومان وفق البطاقة الرسمية؛ ليست ضمان قبول.","conditions":"جواز صالح لأكثر من 6 أشهر. الإلغاء قبل الدخول وخلال صلاحية التأشيرة؛ استثناء التأشيرة السياحية بعد الدخول مرتبط بطلب تعديل الوضع.","specialCases":"ICP","scopeUnresolved":false,"officialSteps":["قدم طلب إلغاء إذن الدخول وراجع بياناته لدى ICP.","أرفق المستندات غير المسترجعة إلكترونيًا.","سدد الرسوم المنطبقة.","تابع قرار الهيئة ونتيجة الإلغاء."]},{"slug":"تصريح-بقاء-خارج-الدولة-لأكثر-من-6-أشهر-عبر-icp","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=68e352d65ae59b00117383fc","requirements":["إثبات سبب البقاء خارج الدولة لأكثر من ستة أشهر."],"fees":"100 درهم لكل شهر تأخير بعد ستة أشهر، و100 للخدمات الذكية. تذكر الشروط 100 لكل 30 يومًا أو أقل؛ راجع احتساب المدة لدى الهيئة.","duration":"يومان وفق البطاقة الرسمية؛ ليست ضمان قبول.","conditions":"خارج الدولة بعد 180 يومًا، وباقي الإقامة أكثر من 30 يومًا وسبب مقبول؛ الدخول خلال 30 يومًا من الموافقة شاملًا يومها. لا يشمل دبي. يستثني المصدر الإقامات الذهبية والخضراء والزرقاء وزوج المواطنة المكفول لديها مع إقامة سارية.","specialCases":"ICP","scopeUnresolved":false,"officialSteps":["قدم الطلب من خارج الدولة عبر ICP.","أرفق إثبات السبب وراجع البيانات.","سدد الرسوم المنطبقة.","تابع القرار والتزم بموعد الدخول عند الموافقة."]},{"slug":"تأسيس-شركة-في-المنطقة-الحرة-بالفجيرة","sourceUrl":"https://digital.fujairah.ae/public/portal/?department=/sites/FujairahFreeZone&service=1","requirements":["صور جوازات أعضاء المجلس والمساهمين والمسؤول وصور شخصية واستمارات الطلب والتأسيس.","للمقيم: نسخة التأشيرة والهوية الإماراتية.","للشركة الأم بحسب الشكل القانوني: قرار المجلس والوكالة وشهادة التأسيس والعقد والرخصة السارية ومستند الملكية النهائية، مصدقة حسب البطاقة.","للفرع: آخر تقرير تدقيق؛ وترد شهادة حسن سلوك ضمن القائمة الرسمية."],"fees":"تعتمد الرسوم على النشاط والمنشأة؛ لا تنشر البطاقة مبلغًا ثابتًا.","duration":"ساعة عمل واحدة لتقديم خدمة تسجيل الرخصة وفق البطاقة؛ لا تمثل كامل تأسيس الشركة أو ضمان صدور الموافقة.","conditions":"الموافقة الأمنية مطلوبة قبل تسجيل الرخصة. يلزم تحديد الملاك والاسم والنشاط. الشركة الأم بعمر 12 شهرًا على الأقل للتأهل لفرع.","specialCases":"المسار يحدد الجهة ومعرّف الخدمة، وليس الصفحة الرئيسية للحكومة الرقمية.","scopeUnresolved":false,"officialSteps":["احصل على الموافقة الأمنية المطلوبة قبل تسجيل الرخصة.","قدم بيانات التسجيل عبر موقع هيئة المنطقة الحرة.","يراجع قسم التراخيص البيانات ويطلب استكمال النواقص.","بعد الموافقة المبدئية، سدد الرسوم المطلوبة وأكمل المستندات."]},{"slug":"إصدار-تصريح-إقامة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e64","requirements":["المستندات المشتركة: جواز السفر وصورة شخصية.","مرفقات إضافية بحسب الفئة، مثل التأمين الصحي والسكن والقرابة أو تصريح العمل؛ القائمة النهائية في اختيار الفئة الرسمي."],"fees":"البنود العامة: 100 درهم للطلب، 100 لكل سنة إقامة، و100 خدمات ذكية. ترد رسوم وضمانات إضافية لبعض الفئات، ومنها 500 لتعديل الوضع؛ لا يوجد إجمالي موحد.","duration":"يومان وفق بطاقة إصدار الإقامة العامة؛ لا يمثل ضمان قبول فئة بعينها.","conditions":"غير موثق بعد","specialCases":"هذه بيانات البطاقة العامة فقط؛ لم تُحسم متطلبات كل فئة. لا تستخدمها لإثبات أهلية إقامة الوالدين أو المولود أو العمل.","scopeUnresolved":true,"officialSteps":[]},{"slug":"إصدار-تأشيرة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e60","requirements":["المستندات المشتركة: جواز السفر وصورة شخصية.","تختلف الإضافات حسب الغرض: مثل إثبات القرابة أو برنامج الرحلة أو التقرير الطبي؛ راجع الفئة المحددة."],"fees":"لبعض فئات الزيارة: 100 درهم للطلب، وإصدار 100 للشهر للدخول الواحد أو 200 للمتعدد، و100 خدمات ذكية؛ ضمان 1000 أو 2000 و20 للإيداع بحسب الفئة. ليست تسعيرة لكل غرض تأشيرة.","duration":"يومان وفق بطاقة إصدار التأشيرة العامة؛ لا يمثل ضمان قبول.","conditions":"غير موثق بعد","specialCases":"البطاقة تضم أغراضًا وفئات متعددة. هذه بيانات مشتركة ومشروطة؛ لا تحسم أهلية استكشاف العمل أو الأعمال أو زيارة قريب.","scopeUnresolved":true,"officialSteps":[]},{"slug":"تجديد-تصريح-إقامة-عبر-icp-خارج-دبي","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e66","requirements":["المستندات المشتركة: جواز السفر وصورة شخصية.","بحسب الفئة: التأمين والسكن والقرابة أو المستندات المهنية؛ طابق قائمة الفئة الرسمية قبل الإرسال."],"fees":"100 درهم للطلب، و100 لكل سنة تجديد، و100 للخدمات الذكية وفق البطاقة؛ الغرامات والمبالغ الأخرى لا تدخل في هذه البنود.","duration":"يومان وفق بطاقة تجديد الإقامة العامة؛ لا يمثل ضمان قبول.","conditions":"غير موثق بعد","specialCases":"لم يُستكمل توثيق شروط كل فئة. مدد السماح تختلف باختلاف الإقامة، ولا تعني مدة الإنجاز مهلة البقاء القانونية.","scopeUnresolved":true,"officialSteps":[]},{"slug":"إصدار-تأشيرة-سياحية-متعددة-الدخول-لمدة-5-سنوات-عبر-icp","sourceUrl":"https://icp.gov.ae/en/services-details/?serviceid=68f5bc968c587a0011cb16cd","requirements":["جواز وصورة؛ كشف ستة أشهر برصيد 4000 دولار أو ما يعادله؛ تذكرة عودة وإثبات سكن.","نسخة هوية شخصية للأفغان والإيرانيين والعراقيين وفق البطاقة."],"fees":"100 درهم طلب، 500 إصدار، 100 خدمات ذكية، وضمان مالي 3000 و20 رسم إيداع؛ افصل الضمان عن الرسوم.","duration":"يومان وفق البطاقة الرسمية؛ لا يمثل ضمان قبول.","conditions":"غير موثق بعد","specialCases":"تذكر البطاقة إقامة 90 يومًا وتمديدًا إلى 180، وتذكر أيضًا حد 90 يومًا في السنة. لم نحسم التعارض؛ أكد مدة الإقامة مع ICP قبل التخطيط.","scopeUnresolved":true,"officialSteps":[]}]$facts$::jsonb) loop
  select * into strict b from public.hb_service_bindings where service_slug=item->>'slug' and active;
  if exists(select 1 from public.hb_policy_versions where policy_key=b.policy_key and jurisdiction_id is not distinct from b.jurisdiction_id and version=2 and reviewed_by=review_tag) then continue;end if;
  select * into strict p from public.hb_policy_versions where policy_key=b.policy_key and jurisdiction_id is not distinct from b.jurisdiction_id and status='active' for update;
  if p.version<>1 then raise exception 'Unexpected active policy version for %: %',b.service_slug,p.version;end if;
  select s.source_url into strict source_url from public.hb_policy_sources s where s.id=any(p.source_ids) and s.active and s.authority_key=b.authority_key and (s.source_url=item->>'sourceUrl' or (s.source_url ~ '^https://(www\\.)?icp\\.gov\\.ae/' and item->>'sourceUrl' ~ '^https://icp\\.gov\\.ae/' and substring(s.source_url from '[?&]serviceid=([^&]+)')=substring(item->>'sourceUrl' from '[?&]serviceid=([^&]+)')));
  select coalesce(jsonb_agg(value),'[]'::jsonb) into new_rules from jsonb_array_elements(p.rules) where value->>'id' not in ('fees','duration','conditions','special-cases','official-steps') and (value->>'id') not like 'requirement%';
  select new_rules||coalesce(jsonb_agg(jsonb_build_object('id','requirement-reviewed-'||ordinality,'when','[]'::jsonb,'effect','review','reason',value#>>'{}','actions',jsonb_build_array('review_documents'),'sourceRefs',jsonb_build_array(source_url))),'[]'::jsonb) into new_rules from jsonb_array_elements(item->'requirements') with ordinality;
  new_rules:=new_rules||jsonb_build_array(jsonb_build_object('id','fees','when','[]'::jsonb,'effect','review','reason',item->>'fees','actions',jsonb_build_array('review_fees'),'sourceRefs',jsonb_build_array(source_url)),jsonb_build_object('id','duration','when','[]'::jsonb,'effect','review','reason',item->>'duration','actions',jsonb_build_array('review_duration'),'sourceRefs',jsonb_build_array(source_url)),jsonb_build_object('id','conditions','when','[]'::jsonb,'effect','review','reason',item->>'conditions','actions',jsonb_build_array('review_conditions'),'sourceRefs',jsonb_build_array(source_url)),jsonb_build_object('id','special-cases','when','[]'::jsonb,'effect','review','reason',item->>'specialCases','actions',jsonb_build_array('review_special_cases'),'sourceRefs',jsonb_build_array(source_url)));
  if jsonb_array_length(item->'officialSteps')>0 then
   new_rules:=new_rules||jsonb_build_array(jsonb_build_object('id','official-steps','when','[]'::jsonb,'effect','review','reason',(select string_agg(value#>>'{}',' ← ' order by ordinality) from jsonb_array_elements(item->'officialSteps') with ordinality),'actions',jsonb_build_array('review_official_steps'),'sourceRefs',jsonb_build_array(source_url)));
  end if;
  update public.hb_policy_versions set status='retired',effective_until=now() where id=p.id;
  insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id) values(p.policy_key,p.jurisdiction_id,2,now(),'active',new_rules,p.source_ids,review_tag,now(),p.country_pack_id);
  update public.hb_service_bindings set metadata=metadata||jsonb_build_object('fees',item->>'fees','duration',item->>'duration','lastReviewed','2026-10-15','source_scope_unresolved',(item->>'scopeUnresolved')::boolean,'recorded_detail_review','partial-official-fields-2026-10-15') where id=b.id;
 end loop;
end $review$;
commit;
